<script setup>
import {ref,computed,onMounted} from 'vue'
const props=defineProps({apiWrite:{type:Function,required:true},userRole:{type:String,required:true}})
const organizations=ref([]),branches=ref([]),members=ref([]),selected=ref(''),error=ref(''),busy=ref(false)
const editingOrg=ref(false),editingBranch=ref('')
const orgPage=ref(1),branchPage=ref(1),memberPage=ref(1),orgMore=ref(false),branchMore=ref(false),memberMore=ref(false)
const organization=ref({name:'',profile:'universal'}),branch=ref({name:'',timezone:'Asia/Barnaul',address:''}),member=ref({user_id:'',role:'viewer'})
const current=computed(()=>organizations.value.find(o=>o.id===selected.value))
async function load(){try{error.value='';const data=await props.apiWrite(`/api/admin/booking/organizations?page=${orgPage.value}`,'GET');organizations.value=data.organizations;orgMore.value=data.has_more;if(selected.value&&!current.value){selected.value='';branches.value=[];members.value=[]}}catch(e){error.value='Модуль недоступен. Проверьте, что NOVA_BOOKING_ENABLED=true и API перезапущен. '+e.message}}
async function loadBranches(){if(!selected.value)return;try{const data=await props.apiWrite(`/api/admin/booking/organizations/${selected.value}/branches?page=${branchPage.value}`,'GET');branches.value=data.branches;branchMore.value=data.has_more}catch(e){error.value=e.message}}
async function loadMembers(){members.value=[];memberMore.value=false;if(!selected.value||current.value?.role!=='owner')return;try{const data=await props.apiWrite(`/api/admin/booking/organizations/${selected.value}/members?page=${memberPage.value}`,'GET');members.value=data.members;memberMore.value=data.has_more}catch(e){error.value=e.message}}
async function selectOrg(){editingOrg.value=false;editingBranch.value='';branch.value={name:'',timezone:'Asia/Barnaul',address:''};branchPage.value=memberPage.value=1;branches.value=[];members.value=[];error.value='';await Promise.all([loadBranches(),loadMembers()])}
async function createOrg(){busy.value=true;error.value='';try{await props.apiWrite('/api/admin/booking/organizations','POST',organization.value);organization.value={name:'',profile:'universal'};await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function createBranch(){busy.value=true;error.value='';try{const path=`/api/admin/booking/organizations/${selected.value}/branches`;await props.apiWrite(editingBranch.value?`${path}/${editingBranch.value}`:path,editingBranch.value?'PUT':'POST',branch.value);editingBranch.value='';branch.value={name:'',timezone:'Asia/Barnaul',address:''};await loadBranches()}catch(e){error.value=e.message}finally{busy.value=false}}
async function updateOrg(){busy.value=true;error.value='';try{await props.apiWrite(`/api/admin/booking/organizations/${selected.value}`,'PUT',organization.value);editingOrg.value=false;organization.value={name:'',profile:'universal'};await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function editOrg(){organization.value={name:current.value.name,profile:current.value.profile};editingOrg.value=true}
function editBranch(b){branch.value={name:b.name,timezone:b.timezone,address:b.address};editingBranch.value=b.id}
function cancelBranch(){editingBranch.value='';branch.value={name:'',timezone:'Asia/Barnaul',address:''}}
async function saveMember(){busy.value=true;error.value='';try{await props.apiWrite(`/api/admin/booking/organizations/${selected.value}/members`,'POST',member.value);member.value={user_id:'',role:'viewer'};await loadMembers()}catch(e){error.value=e.message}finally{busy.value=false}}
async function removeMember(m){if(!confirm(`Отозвать доступ пользователя ${m.username} к организации?`))return;busy.value=true;error.value='';try{await props.apiWrite(`/api/admin/booking/organizations/${selected.value}/members/${m.id}`,'DELETE');await loadMembers()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template>
 <div class="page-title"><div><h1>Booking &amp; CRM</h1><p>Первый этап: организации, филиалы и доступ</p></div></div>
 <p v-if="error" class="alert" role="alert">{{error}}</p>
 <div class="panel" style="padding:20px;margin-bottom:20px"><h2>Организации</h2><form v-if="userRole==='owner' && !editingOrg" @submit.prevent="createOrg" style="display:flex;flex-wrap:wrap;gap:10px"><input v-model="organization.name" class="search-input" placeholder="Название организации" maxlength="150" required><select v-model="organization.profile" class="search-input"><option value="universal">Универсальный бизнес</option><option value="dentistry">Стоматология</option><option value="beauty">Салон красоты</option><option value="automotive">Автосервис</option></select><button class="primary-btn" :disabled="busy">Создать организацию</button></form><p>Профиль пока сохраняется как настройка. Организацию создаёт владелец NOVA.</p><label>Выберите организацию <select v-model="selected" @change="selectOrg" class="search-input"><option value="">Выберите организацию</option><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}} ({{o.role}})</option></select></label><div><button class="row-btn" :disabled="orgPage===1" @click="orgPage--;load()">Назад</button> Страница {{orgPage}} <button class="row-btn" :disabled="!orgMore" @click="orgPage++;load()">Далее</button></div></div>
 <template v-if="selected"><div v-if="current?.role==='owner'" class="panel" style="padding:20px;margin-bottom:20px"><button v-if="!editingOrg" class="row-btn" @click="editOrg">Изменить организацию</button><form v-else @submit.prevent="updateOrg" style="display:flex;flex-wrap:wrap;gap:10px"><input v-model="organization.name" class="search-input" maxlength="150" required aria-label="Название организации"><select v-model="organization.profile" class="search-input" aria-label="Профиль организации"><option value="universal">Универсальный бизнес</option><option value="dentistry">Стоматология</option><option value="beauty">Салон красоты</option><option value="automotive">Автосервис</option></select><button class="primary-btn" :disabled="busy">Сохранить</button><button type="button" class="row-btn" @click="editingOrg=false;organization={name:'',profile:'universal'}">Отмена</button></form></div><div class="panel" style="padding:20px;margin-bottom:20px"><h2>Филиалы</h2><form v-if="current?.role!=='viewer'" @submit.prevent="createBranch" style="display:flex;flex-wrap:wrap;gap:10px;margin:16px 0"><input v-model="branch.name" class="search-input" placeholder="Название филиала" maxlength="150" required><input v-model="branch.timezone" class="search-input" placeholder="Часовой пояс, например Asia/Barnaul" required><input v-model="branch.address" class="search-input" placeholder="Адрес" maxlength="300"><button class="primary-btn" :disabled="busy">{{editingBranch?'Сохранить филиал':'Добавить филиал'}}</button><button v-if="editingBranch" type="button" class="row-btn" @click="cancelBranch">Отмена</button></form><ul><li v-for="b in branches" :key="b.id">{{b.name}} — {{b.timezone}} <span v-if="b.address">— {{b.address}}</span> <button v-if="current?.role!=='viewer'" class="row-btn" @click="editBranch(b)">Изменить</button></li></ul><p v-if="!branches.length">Филиалов на этой странице нет.</p><button class="row-btn" :disabled="branchPage===1" @click="branchPage--;loadBranches()">Назад</button> Страница {{branchPage}} <button class="row-btn" :disabled="!branchMore" @click="branchPage++;loadBranches()">Далее</button></div>
 <div v-if="current?.role==='owner'" class="panel" style="padding:20px"><h2>Доступ к организации</h2><p>Сначала создайте учётную запись NOVA с ролью администратор или менеджер в разделе «Доступ и безопасность». Укажите её ID ниже. Права NOVA остаются в силе.</p><form @submit.prevent="saveMember" style="display:flex;flex-wrap:wrap;gap:10px"><input v-model="member.user_id" class="search-input" inputmode="numeric" pattern="[1-9][0-9]*" placeholder="ID учётной записи NOVA" required><select v-model="member.role" class="search-input"><option value="viewer">Наблюдатель: просмотр</option><option value="manager">Менеджер: управление филиалами</option></select><button class="primary-btn" :disabled="busy">Сохранить доступ</button></form><ul><li v-for="m in members" :key="m.id">{{m.username}} (ID {{m.id}}) — {{m.role}}<span v-if="!m.enabled">, учётная запись отключена</span> <button v-if="m.role!=='owner'" class="row-btn danger" :disabled="busy" @click="removeMember(m)">Отозвать</button></li></ul><button class="row-btn" :disabled="memberPage===1" @click="memberPage--;loadMembers()">Назад</button> Страница {{memberPage}} <button class="row-btn" :disabled="!memberMore" @click="memberPage++;loadMembers()">Далее</button></div></template>
</template>
